// ✅ Struct ideal: resultado de hit detection (pequeño, copiado por valor, temporal)
public struct HitResult
{
    public bool didHit;
    public float distance;
    public Vector3 point;
    public Vector3 normal;
}

// ✅ Unity usa struct para Vector2, Vector3, Color, Quaternion — son pequeños y se copian con frecuencia
// Vector3 a = transform.position; // copia por valor — intencional

// ❌ Struct inapropiado: entidad con identidad propia y estado mutable complejo
public struct Enemy   // MAL: los structs no soportan herencia, no pueden ser null,
{                     // y copiar un Enemy grande en cada asignación penaliza la performance
    public string name;
    public float health;
    public float mana;
    public List<Item> inventory; // referencia dentro de struct — confuso
    public AIStateMachine ai;   // estado complejo — usa clase
}

// ✅ Regla práctica: struct si cumple los 3 criterios:
// 1. Pequeño (≤ 16 bytes es ideal)
// 2. Inmutable o copiado intencionalmente
// 3. No necesita herencia ni null

